import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
const failures = []
async function openPage(viewport, mobile = false) {
  const page = await browser.newPage({ viewport, isMobile: mobile, hasTouch: mobile })
  page.on('pageerror', e => failures.push(e.message))
  page.on('console', m => { if (m.type() === 'error') failures.push(m.text()) })
  page.on('response', r => { if (r.status() >= 400 && new URL(r.url()).origin === 'http://127.0.0.1:3002') failures.push(`HTTP ${r.status()} ${r.url()}`) })
  await page.route('**/game.js', async route => {
    const response = await route.fetch()
    let body = await response.text()
    body = body.replace("updateLevel();roster();render();\n})();", "updateLevel();roster();render();window.__gameTest={get:()=>({player,allies,enemies,props,projectiles,running,matchEnded,profile}),attack,castSkill,damageProp,damageTarget,checkEnd,updateProjectiles,nearestProp};\n})();")
    await route.fulfill({ response, body })
  })
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' })
  return page
}
try {
  const desktop = await openPage({ width: 1440, height: 900 })
  await desktop.locator('#start-button').click()
  await desktop.waitForFunction(() => window.__gameTest?.get().running)
  const core = await desktop.evaluate(() => {
    const t = window.__gameTest, s = t.get(), p=s.player
    const prop={x:p.x+10,y:p.y,r:4,hp:2,kind:'crate'}
    s.props.push(prop); p.attackCD=0; t.attack(p)
    const propHit=prop.hp===1
    const foe=s.enemies[0]; foe.x=p.x+20;foe.y=p.y;foe.hp=foe.maxHp
