const errors=[]
const page=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:1})
page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())})
try {
 await page.route('**/game.js',async route=>{const response=await route.fetch();let body=await response.text();body=body.replace("updateLevel();roster();renderHeroInfo();initProps();render();\n})();","updateLevel();roster();renderHeroInfo();initProps();render();window.__gameTest={get:()=>({player,running}),};\n})();");await route.fulfill({response,body})})
 await page.goto('http://127.0.0.1:3002',{waitUntil:'load'});await page.locator('#start-button').click();await page.waitForFunction(()=>window.__gameTest?.get().running)
 const before=await page.evaluate(()=>({x:window.__gameTest.get().player.x,y:window.__gameTest.get().player.y}))
 const rect=await page.locator('#stick-zone').boundingBox();if(!rect)throw Error('Joystick not visible')
 const cdp=await page.context().newCDPSession(page)
 const x=rect.x+rect.width/2,y=rect.y+rect.height/2
 await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y,id:1}]})
 await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:x+34,y,id:1}]})
 await page.waitForTimeout(800)
 const during=await page.evaluate(()=>({x:window.__gameTest.get().player.x,y:window.__gameTest.get().player.y}))
 await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]})
 const afterEnd=await page.evaluate(()=>({x:window.__gameTest.get().player.x,y:window.__gameTest.get().player.y}))
 const skill=await page.locator('[data-action="skill1"]').boundingBox();if(!skill)throw Error('Skill button not visible')
 await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:skill.x+skill.width/2,y:skill.y+skill.height/2,id:2}]})
 await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]})
 const chakra=await page.evaluate(()=>window.__gameTest.get().player.ch)
 if(during.x<=before.x||chakra>=92||errors.length)throw Error(JSON.stringify({before,during,afterEnd,chakra,errors}))
