import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const errors = []
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 })
page.on('pageerror', e => errors.push(e.message))
try {
  await page.route('**/game.js', async route => {
    const response = await route.fetch()
    let body = await response.text()
    body = body.replace('updateLevel();roster();renderHeroInfo();initProps();render();\n})();', 'updateLevel();roster();renderHeroInfo();initProps();render();window.__gameTest={get:()=>({player,allies,enemies,running,elapsed,joystick,pointer})};\n})();')
    await route.fulfill({ response, body })
  })
  await page.goto('http://127.0.0.1:3002')
  await page.locator('#start-button').click()
  const z = await page.locator('#stick-zone').boundingBox()
  const cdp = await page.context().newCDPSession(page)
  await page.evaluate(() => {
    window.__pointerEvents = []
    for (const type of ['pointerdown', 'pointermove', 'pointerup', 'pointercancel', 'touchstart', 'touchmove', 'touchend']) {
      document.querySelector('#stick-zone').addEventListener(type, e => window.__pointerEvents.push({ type, clientX: e.clientX, clientY: e.clientY, pointerType: e.pointerType }), true)
    }
  })
  const x = z.x + z.width / 2, y = z.y + z.height / 2
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x, y, id: 1 }] })
  await page.waitForTimeout(100)
  const start = await page.evaluate(() => ({ game: window.__gameTest.get(), events: window.__pointerEvents }))
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: x + 34, y, id: 1 }] })
  await page.waitForTimeout(800)
  const during = await page.evaluate(() => ({ game: window.__gameTest.get(), events: window.__pointerEvents }))
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] })
  const end = await page.evaluate(() => ({ game: window.__gameTest.get(), events: window.__pointerEvents }))
  await page.waitForTimeout(120000)
  const battle = await page.evaluate(() => {
    const s = window.__gameTest.get()
    const details = units => units.map(u => ({ name: u.hero.name, x: Math.round(u.x), y: Math.round(u.y), hp: Math.round(u.hp), alive: u.alive, target: u.target && u.target.hero.name, atk: u.attackCD }))
    return { elapsed: s.elapsed, allies: details(s.allies), enemies: details(s.enemies), result: document.querySelector('#result-title').textContent }
  })
  console.log(JSON.stringify({ z, start, during, end, battle, errors }, null, 2))
} finally { await browser.close() }

